/* @lc app=leetcode id=2835 lang=kotlin */
class Solution { fun minOperations(nums: List<Int>, target: Int): Int = if (nums.sumOf { it.toLong() } < target) -1 else LongArray(31).apply { nums.forEach { x -> (kotlin.math.log2(x.toDouble()).toInt()).let { this[it] = this[it] + 1 } } }.let { count -> longArrayOf(0).let { state -> (0 until 30).forEach { i -> (if ((target.toLong() shr i) and 1L == 1L) if (count[i] > 0) count[i] = count[i] - 1 else (i + 1 until 31).first { count[it] > 0 }.let { j -> (count[j] - 1).also { count[j] = it }.also { (i until j).forEach { k -> (count[k] + 1).also { count[k] = it }.also { state[0] = state[0] + 1 } } } } else Unit).also { count[i + 1] = count[i + 1] + count[i] / 2 } }.run { state[0].toInt() } } }